function(ctx) {
      const repo = repoById(ctx.id);
      const branch = ctx.data.branch;
      const f = ctx.form || {};
      const u = ui();
      const path = String(f.path || '');
      const message = String(f.message || '').trim();
      // A rejected submission keeps what was typed, so the reason can be read and corrected.
      u.fileDraft = { path: path, content: String(f.content || ''), message: String(f.message || '') };
      if (!canWrite(repo, me())) { u.fileError = 'Access denied'; ARC.render(); return; }
      if (ruleFor(repo, branch)) { u.fileError = 'Branch is protected'; ARC.render(); return; }
      if (!path || path.startsWith('/') || path.split('/').indexOf('..') !== -1) { u.fileError = 'Invalid file path'; ARC.render(); return; }
      if (fileOn(repo, branch, path) || entriesOf(repo, branch, '').some((e) => e.name === path && e.type === 'dir')) { u.fileError = 'Invalid file path'; ARC.render(); return; }
      if (!message || message.length > 72) { u.fileError = 'Commit message is required'; ARC.render(); return; }
      list('files').push({ id: uid('f'), repoId: repo.id, branch: branch, path: path, content: String(f.content || '') });
      const b = branchList(repo).find((x) => x.name === branch);
      const cid = uid('c');
      const addedLines = String(f.content || '').split('\n').map((t) => ({ type: 'add', text: t }));
      list('commits').push({ id: cid, repoId: repo.id, branch: branch, seq: 99, message: message, author: (me() || {}).username || '', at: 'just now', parent: b ? b.commitId : null, additions: addedLines.length, deletions: 0, files: [{ path: path, additions: addedLines.length, deletions: 0, lines: addedLines }] });
      if (b) b.commitId = cid;
      for (const p of list('pulls')) {
        if (p.repoId === repo.id && p.compare === branch && p.status !== 'Merged') p.compareCommit = cid;
      }
      u.fileError = '';
      u.fileDraft = null;
      ARC.save();
      ARC.navigate(codeHref(repo, branch, path));
    }

function reviewsFor(pr) {
  const reviews = list('reviews').filter((r) => r.prId === pr.id && r.commit === pr.compareCommit);
  const effective = [];
  for (const r of reviews) {
    const i = effective.findIndex((x) => x.reviewerId === r.reviewerId);
    if (i === -1) effective.push(r);
    else effective[i] = r;
  }
  return effective;
}

function eligibility(repo, pr, user) {
  if (pr.status === 'Draft') return { ok: false, reason: '' };
  if (pr.status !== 'Open') return { ok: false, reason: '' };
  const rule = ruleFor(repo, pr.base);
  const revs = reviewsFor(pr);
  if (revs.some((r) => r.decision === 'Request changes')) return { ok: false, reason: 'Changes requested' };
  if (rule) {
    const approvals = revs.filter((r) => r.decision === 'Approve' && r.reviewerId !== pr.authorId);
    if (rule.requireApproval && approvals.length < 1) return { ok: false, reason: 'Review required by branch protection' };
    if (rule.requireCheck) {
      const chk = checkFor(pr);
      if (!chk || chk.status !== 'success') return { ok: false, reason: 'Review required by branch protection' };
    }
  }
  if (!canMaintain(repo, user)) return { ok: false, reason: 'You do not have permission to merge this pull request.' };
  return { ok: true, reason: '' };
}

function repoRole(repo, user) {
  if (!repo) return null;
  if (!user) return repo.visibility === 'Public' ? 'Read' : null;
  if (repo.ownerType === 'user' && repo.ownerSlug === user.username) return 'Admin';
  if (repo.ownerType === 'org' && isOrgOwner(repo.orgId, user)) return 'Admin';
  let best = null;
  for (const g of list('grants')) {
    if (g.repoId !== repo.id) continue;
    if (g.subjectType === 'user' && g.subjectId === user.id) best = better(best, g.role);
    if (g.subjectType === 'team' && isTeamMember(g.subjectId, user.id)) best = better(best, g.role);
  }
  if (best) return best;
  if (repo.visibility === 'Public') return 'Read';
  return null;
}

function isOrgOwner(orgId, user) {
  return !!user && list('memberships').some((m) => m.orgId === orgId && m.userId === user.id && m.role === 'Owner');
}

