functions.code:
function(ctx) {
      const f = ctx.form || {};
      const u = ui();
      const user = me();
      const name = String(f.name || '').trim();
      const ownerLabel = String(f.owner || '');
      const org = list('orgs').find((o) => o.displayName === ownerLabel);
      // A rejected submission keeps what was typed, so the reason can be read and corrected.
      u.repoForm = { owner: ownerLabel, name: String(f.name || ''), description: String(f.description || ''), visibility: f.visibility, readme: !!f.readme };
      if (!name) { u.repoError = 'Repository name is required'; ARC.render(); return; }
      const ownerSlug = org ? org.identifier : ownerLabel;
      if (list('repos').some((r) => r.ownerSlug === ownerSlug && r.name === name)) { u.repoError = 'Name already exists on this account'; ARC.render(); return; }
      const repo = {
        id: uid('repo'), owner: ownerLabel, ownerType: org ? 'org' : 'user', orgId: org ? org.id : null,
        ownerSlug: ownerSlug, name: name,
        visibility: f.visibility === 'Private' ? 'Private' : 'Public',
        description: String(f.description || ''), defaultBranch: 'main', updated: 'just now', createdBy: user.id, forkOf: null
      };
      list('repos').push(repo);
      list('branches').push({ id: uid('br'), repoId: repo.id, name: 'main', commitId: 'c-' + repo.id + '-1' });
      list('commits').push({ id: 'c-' + repo.id + '-1', repoId: repo.id, branch: 'main', seq: 1, message: 'Initial commit', author: user.username, at: 'just now', parent: null, additions: 1, deletions: 0, files: [] });
      if (f.readme) {
        list('files').push({ id: uid('f'), repoId: repo.id, branch: 'main', path: 'README.md', content: '# ' + name + '\n' });
      }
      u.repoError = '';
      u.repoForm = null;
      ARC.save();
      ARC.navigate(repoBase(repo));
    }

