functions.code:
function(ctx) {
      const issue = list('issues').find((i) => i.id === ctx.id);
      const f = ctx.form || {};
      const u = ui();
      const title = String(f.title || '').trim();
      if (!title || title.length > 256) { u.editError = 'Title is required'; ARC.render(); return; }
      issue.title = title;
      list('activities').push({ id: uid('ac'), issueId: issue.id, text: ((me() || {}).username || '') + ' edited the title', at: now() });
      u.editingTitle = false;
      u.editError = '';
      ARC.save();
      ARC.render();
    }

